#!/usr/bin/env python3
"""Structural audit of the GMRI research handoff. Not a substitute for QAQI.

No non-stdlib dependencies. Never modifies the research output, the source PDF,
or any external system. A failure report at the start of research is expected.
"""
import argparse
import hashlib
import json
from pathlib import Path
from typing import Any


def sha256(path: Path) -> str:
    hasher = hashlib.sha256()
    with path.open('rb') as fh:
        for block in iter(lambda: fh.read(1024 * 1024), b''):
            hasher.update(block)
    return hasher.hexdigest()


def load_json(path: Path, issues: list[str], label: str) -> Any:
    try:
        return json.loads(path.read_text(encoding='utf-8'))
    except (OSError, ValueError) as exc:
        issues.append(f'{label}: cannot parse JSON: {exc}')
        return None


def audit(root: Path, contract: dict, source_dir: Path) -> dict:
    blocking: list[str] = []
    warnings: list[str] = []
    present = 0
    qvalid = 0
    groups_present = 0
    source_count = 0
    root = Path(root)
    source_dir = Path(source_dir)

    pdf = source_dir / contract['source_pdf_relpath']
    if not pdf.is_file():
        blocking.append(f'Authoritative original PDF absent: {pdf}')
    elif sha256(pdf) != contract['source_pdf_sha256']:
        blocking.append('Authoritative original PDF hash mismatch: do not substitute changed instructions.')

    deliverables = {d['id']: d for d in contract['deliverables']}
    if len(deliverables) != 18:
        blocking.append('Contract error: expected 18 unique deliverables.')
    for did, obj in deliverables.items():
        path = root / obj['path']
        if not path.is_file():
            blocking.append(f'{did}: missing deliverable file: {obj["path"]}')
        elif path.stat().st_size < 400:
            blocking.append(f'{did}: report too short to pass minimum structural review: {obj["path"]}')
        else:
            present += 1

    groups = contract.get('required_supporting_artifacts', [])
    for group in groups:
        candidates = [p for p in root.glob(group['glob']) if p.is_file() and p.stat().st_size > 10]
        if not candidates:
            blocking.append(f'Required artifact group missing/empty: {group["name"]} ({group["glob"]})')
        else:
            groups_present += 1

    ans_file = root / 'REQUIREMENTS/research-acceptance-84.json'
    if ans_file.exists():
        data = load_json(ans_file, blocking, '84-question matrix')
        if data is not None:
            answers = data.get('answers') if isinstance(data, dict) else data
            if not isinstance(answers, list):
                blocking.append('84-question matrix must be a list or {"answers": [..]}.')
            else:
                indexed: dict = {}
                for row in answers:
                    if not isinstance(row, dict) or not isinstance(row.get('id'), str):
                        blocking.append('84-question matrix contains an unidentifiable row.')
                        continue
                    if row['id'] in indexed:
                        blocking.append(f'84-question matrix duplicate ID {row["id"]}.')
                    indexed[row['id']] = row
                expected = {q['id'] for q in contract['questions']}
                for qid in sorted(expected):
                    entry = indexed.get(qid)
                    if entry is None:
                        blocking.append(f'84-question matrix missing {qid}.')
                        continue
                    st = entry.get('status')
                    if st == 'ANSWERED':
                        if len(str(entry.get('answer') or '').strip()) < 30:
                            blocking.append(f'{qid}: ANSWERED requires a substantive answer.')
                        elif not entry.get('evidence_refs'):
                            blocking.append(f'{qid}: ANSWERED must link evidence_refs.')
                        else:
                            qvalid += 1
                    elif st == 'FUTURE_PHYSICAL_TEST':
                        if not all(len(str(entry.get(k) or '').strip()) >= 12 for k in ('reason', 'procedure', 'pass_fail')):
                            blocking.append(f'{qid}: FUTURE_PHYSICAL_TEST needs reason, procedure and pass_fail criteria.')
                        else:
                            qvalid += 1
                    elif st == 'UNRESOLVED_SOURCE':
                        blocking.append(f'{qid}: unresolved source/material question; research cannot claim complete.')
                    else:
                        blocking.append(f'{qid}: unknown/unanswered status {st!r}.')
                for qid in indexed:
                    if qid not in expected:
                        blocking.append(f'84-question matrix contains unrecognized {qid}.')

    manifest_file = root / 'HANDOFF_MANIFEST.json'
    if manifest_file.exists():
        manifest = load_json(manifest_file, blocking, 'handoff manifest')
        if isinstance(manifest, dict):
            if manifest.get('source_pdf_sha256') != contract['source_pdf_sha256']:
                blocking.append('HANDOFF_MANIFEST source PDF SHA mismatch.')
            rows = manifest.get('deliverables')
            if not isinstance(rows, dict):
                blocking.append('HANDOFF_MANIFEST deliverables must be a map keyed D01..D18.')
            else:
                for did, obj in deliverables.items():
                    meta = rows.get(did)
                    if not isinstance(meta, dict):
                        blocking.append(f'HANDOFF_MANIFEST missing {did} entry.')
                        continue
                    rel = meta.get('path')
                    if rel != obj['path']:
                        blocking.append(f'{did}: manifest path differs from contracted deliverable.')
                        continue
                    path = root / rel
                    if path.is_file() and meta.get('sha256') != sha256(path):
                        blocking.append(f'{did}: manifest SHA-256 differs from actual file.')
                    if meta.get('status') != 'COMPLETE_REVIEWED':
                        blocking.append(f'{did}: report not independently reviewed (status must be COMPLETE_REVIEWED).')
                    if not meta.get('evidence_refs'):
                        blocking.append(f'{did}: manifest needs evidence_refs.')

    sources = root / 'RESEARCH/source-register.jsonl'
    if sources.is_file():
        for n, line in enumerate(sources.read_text(encoding='utf-8').splitlines(), 1):
            if not line.strip():
                continue
            try:
                entry = json.loads(line)
            except ValueError:
                blocking.append(f'Source-register line {n}: malformed JSON.')
                continue
            if not isinstance(entry, dict) or not str(entry.get('url') or '').startswith(('https://','http://')):
                blocking.append(f'Source-register line {n}: invalid URL.')
            elif not entry.get('source_id') or not entry.get('retrieved_at') or not entry.get('claims_supported'):
                blocking.append(f'Source-register line {n}: missing provenance fields.')
            else:
                source_count += 1
        if source_count == 0:
            blocking.append('No valid primary/secondary research source records found.')
        else:
            warnings.append(f'{source_count} source-register entries counted; truth and source quality require independent review.')

    gates_file = root / 'TRUST/gates.json'
    if gates_file.exists():
        doc = load_json(gates_file, blocking, 'gates contract')
        if isinstance(doc, dict):
            rows = doc.get('gates', [])
            ids = {x.get('id') for x in rows if isinstance(x, dict)}
            if ids != {f'G{i}' for i in range(9)}:
                blocking.append('Gate contract must specify exactly G0..G8.')
            for gate in rows:
                if not isinstance(gate, dict):
                    continue
                for field in ('owner', 'entry', 'proof', 'failure', 'remediation', 'authority'):
                    if not gate.get(field):
                        blocking.append(f'{gate.get("id", "Unknown Gate")}: missing {field}.')

    review_file = root / 'EVIDENCE/research-review.json'
    if review_file.exists():
        data = load_json(review_file, blocking, 'research review')
        if isinstance(data, dict):
            if data.get('status') != 'PASS':
                blocking.append('Independent research review is not PASS.')
            if not data.get('reviewer_id') or data.get('reviewer_id') == data.get('author_id'):
                blocking.append('Research review lacks distinct held-out reviewer identity.')
            if not data.get('tested_artifacts') or not data.get('source_comparison'):
                blocking.append('Research review lacks tested_artifacts or source_comparison.')

    # This code deliberately tests presence and consistency, not factual correctness.
    warnings.append('Structural audit only. It cannot certify factual validity, implemented runtime integration, independent QAQI, or investigator acceptance.')
    return {
        'structurally_complete': not blocking,
        'source_pdf_verified': pdf.is_file() and sha256(pdf) == contract['source_pdf_sha256'],
        'deliverables_present': present,
        'deliverables_required': len(deliverables),
        'questions_valid': qvalid,
        'questions_required': len(contract['questions']),
        'supporting_artifact_groups_present': groups_present,
        'supporting_artifact_groups_required': len(groups),
        'sources_indexed': source_count,
        'blocking': blocking,
        'warnings': warnings,
    }


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--root', type=Path, default=Path('OUTPUT/GMRI_ENGINEERING_FACTORY'))
    parser.add_argument('--contract', type=Path, default=Path('RESEARCH_RUN_CONTRACT.json'))
    parser.add_argument('--json', action='store_true', help='print the full JSON audit result')
    args = parser.parse_args()
    if not args.contract.is_file():
        parser.error(f'Contract not found: {args.contract}')
    contract = json.loads(args.contract.read_text(encoding='utf-8'))
    result = audit(args.root, contract, source_dir=args.contract.resolve().parent)
    if args.json:
        print(json.dumps(result, indent=2, ensure_ascii=False))
    else:
        print('GMRI RESEARCH STRUCTURAL AUDIT:', 'READY FOR INDEPENDENT CONTENT AUDIT' if result['structurally_complete'] else 'INCOMPLETE')
        print(f'Deliverables: {result["deliverables_present"]}/{result["deliverables_required"]}; 84Q answers: {result["questions_valid"]}/{result["questions_required"]}; supporting groups: {result["supporting_artifact_groups_present"]}/{result["supporting_artifact_groups_required"]}; source entries: {result["sources_indexed"]}')
        for issue in result['blocking'][:80]:
            print('BLOCK:', issue)
        if len(result['blocking']) > 80:
            print(f'... and {len(result["blocking"]) - 80} additional blockers; run --json for all.')
        for warning in result['warnings']:
            print('NOTE:', warning)
    return 0 if result['structurally_complete'] else 2


if __name__ == '__main__':
    raise SystemExit(main())
